import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun.hanjuku import orchestrator as O
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen

PICKER = '00〜37の きょくばんを しじしてください。Bボタンで しゅうりょうできます。'


def test_the_explicit_b_instruction_overrides_an_exhausted_budget(monkeypatch):
    mem = {'concert_picker_watch': {'b_count': 9, 'exhausted': True}, '_records': []}
    screen = Screen([], None, PICKER, kind='text')
    # the concert block runs late in decide(); call the shared helper directly
    actions = O.concert_b_instruction_step('concert', 'text', screen, mem, 'digest')
    assert actions == [O.pad('b')]
    assert mem['concert_picker_watch'] == {'b_count': 0, 'exhausted': False,
                                           'instruction_seen': True}
    assert any(r['decision'] == 'concert_picker_b_instruction' for r in mem['_records'])
